<div class="col-xl-4">
<?php if ($canChange): $commercialAction=$license['license_type']==='perpetual'?'maintenance':'renew'; ?><form class="panel form-panel" method="post" action="/admin/licenses/<?= V::escape($licenseId) ?>/<?= $commercialAction ?>"><?php V::fields($csrf); ?><input type="hidden" name="version" value="<?= (int)$license['row_version'] ?>"><span class="eyebrow"><?= $commercialAction==='maintenance'?'COMPRA SEPARADA':'VIGENCIA' ?></span><h2 class="mt-3"><?= $commercialAction==='maintenance'?'Registrar mantenimiento':'Renovar suscripción' ?></h2><p class="text-secondary small"><?= $commercialAction==='maintenance'?'Registra una compra autorizada para extender el acceso a nuevas versiones.':'Define la nueva fecha contratada. La renovación no se aplica automáticamente.' ?></p><div class="stack-form"><div><label class="form-label" for="until">Nueva fecha límite <span class="optional">UTC</span></label><input class="form-control" type="datetime-local" id="until" name="until" required></div><div><label class="form-label" for="reference">Referencia comercial</label><input class="form-control" id="reference" name="reference" maxlength="190" <?= $commercialAction==='maintenance'?'required':'' ?>></div><div><label class="form-label" for="term_reason">Motivo / autorización</label><textarea class="form-control" id="term_reason" name="reason" maxlength="500" rows="2" required></textarea></div><button class="btn btn-primary" type="submit"><?= $commercialAction==='maintenance'?'Registrar compra':'Confirmar renovación' ?></button></div></form>
<section class="panel form-panel mt-4"><h2>Clave comercial</h2><p class="text-secondary small">La clave existente no se puede recuperar. Reemplazarla invalida su uso para nuevas activaciones.</p><details><summary>Reemplazar clave</summary><form class="stack-form mt-3" method="post" action="/admin/licenses/<?= V::escape($licenseId) ?>/reissue"><?php V::fields($csrf); ?><input type="hidden" name="version" value="<?= (int)$license['row_version'] ?>"><label>Motivo<input class="form-control mt-2" name="reason" maxlength="500" required></label><label>Tu contraseña<input class="form-control mt-2" name="password" type="password" autocomplete="current-password" required></label><label>Código de autenticación nuevo<input class="form-control mt-2" name="code" inputmode="numeric" maxlength="6" autocomplete="one-time-code" required></label><button class="btn btn-outline-primary">Generar nueva clave</button></form></details></section>
<?php if ($actor->role==='superadmin'): ?><section class="panel form-panel mt-4 danger-panel"><h2>Revocación</h2><p class="text-secondary small">Impide nuevas activaciones y deja constancia del motivo. Las copias desconectadas no conocen una revocación instantáneamente.</p><details><summary>Revocar esta licencia</summary><form class="stack-form mt-3" method="post" action="/admin/licenses/<?= V::escape($licenseId) ?>/revoke" data-confirm="Se revocará esta licencia. Esta acción no tiene rehabilitación automática."><?php V::fields($csrf); ?><input type="hidden" name="version" value="<?= (int)$license['row_version'] ?>"><label>Motivo de revocación<textarea class="form-control mt-2" name="reason" rows="2" maxlength="500" required></textarea></label><label>Tu contraseña<input class="form-control mt-2" type="password" name="password" autocomplete="current-password" required></label><label>Código de autenticación nuevo<input class="form-control mt-2" name="code" maxlength="6" inputmode="numeric" autocomplete="one-time-code" required></label><button class="btn btn-outline-danger">Confirmar revocación</button></form></details></section><?php endif; ?>
